 async endCall(notify=true){const s=this.call;if(!s)return;this.call=null;clearTimeout(this.ringTimer);s.callRef?.off('value',s.listener);s.pc.onconnectionstatechange=null;s.pc.close();s.stream.getTracks().forEach(t=>t.stop());if(notify)try{await this.connection.ref.child('calls/'+s.id).update({state:'ended'});}catch(_){}const patch={['inbox/'+this.device+'/'+s.id]:null};if(s.to)patch['inbox/'+s.to+'/'+s.id]=null;void this.connection.ref.update(patch).catch(()=>{});setTimeout(()=>void this.connection.ref.child('calls/'+s.id).remove().catch(()=>{}),5000);this.closeDialog();this.toast('CALL ENDED');}
 openReservations(){const e=this.escape;this.openDialog('Reservations',`<label for="resDate">Date</label><input id="resDate" class="field" type="date" value="${this.connection.state.day}"><div id="reservationList" class="reserved-list"></div><form id="reservationForm"><label for="resName">Guest name</label><input id="resName" class="field" maxlength="100" required><div class="form-row"><div><label for="resTime">Time</label><input id="resTime" type="time" class="field" required></div><div><label for="resPeople">Guests</label><input id="resPeople" type="number" class="field" min="1" max="120" value="2" required></div></div><label for="resPhone">Phone · optional</label><input id="resPhone" type="tel" class="field" maxlength="30"><label for="resNote">Notes · optional</label><input id="resNote" class="field" maxlength="300"><button class="primary full" id="saveReservation">SAVE RESERVATION</button></form>`);const render=()=>{const day=document.getElementById('resDate')?.value,box=document.getElementById('reservationList');if(!box)return;box.innerHTML=Object.entries(this.reservations||{}).filter(([,r])=>r.date===day).sort((a,b)=>a[1].time.localeCompare(b[1].time)).map(([id,r])=>`<div class="reservation"><b>${e(r.time)} · ${e(r.name)}</b> · ${r.people} guests<br><span class="quiet">${e(r.phone||'')} ${e(r.note||'')}</span><div class="actions"><button data-res-edit="${e(id)}">EDIT</button><button data-res-delete="${e(id)}">DELETE</button></div></div>`).join('')||'<p class="helper">No reservations for this date.</p>';box.querySelectorAll('[data-res-edit]').forEach(b=>b.onclick=()=>{const r=this.reservations[b.dataset.resEdit];document.getElementById('reservationForm').dataset.editId=b.dataset.resEdit;for(const [field,key]of [['resName','name'],['resTime','time'],['resPeople','people'],['resPhone','phone'],['resNote','note']])document.getElementById(field).value=r[key]||'';});box.querySelectorAll('[data-res-delete]').forEach(b=>b.onclick=async()=>{if(confirm('Delete this reservation?'))try{await this.connection.ref.child('reservations/'+b.dataset.resDelete).remove();this.toast('RESERVATION DELETED');}catch(e){this.toast(e.message);}});};if(!this.reservationWatching){this.reservationWatching=true;this.watch(this.connection.ref.child('reservations'),snap=>{this.reservations=snap.val()||{};render();});}this.drawReservations=render;document.getElementById('resDate').onchange=render;render();document.getElementById('reservationForm').onsubmit=async event=>{event.preventDefault();try{const form=document.getElementById('reservationForm'),id=form.dataset.editId||'res_'+this.connection.now()+'_'+crypto.randomUUID();form.dataset.editId=id;const value={date:document.getElementById('resDate').value,name:document.getElementById('resName').value.trim(),time:document.getElementById('resTime').value,people:Number(document.getElementById('resPeople').value),phone:document.getElementById('resPhone').value.trim(),note:document.getElementById('resNote').value.trim(),at:this.connection.now()};if(!value.date||!value.name||!value.time||!Number.isInteger(value.people)||value.people<1||value.people>120)throw Error('Complete the reservation fields.');await this.connection.ref.child('reservations/'+id).set(value);form.reset();delete form.dataset.editId;document.getElementById('resPeople').value=2;this.toast('RESERVATION SAVED');}catch(e){this.toast(e.message);}};}
 close(){this.unsubs.forEach(fn=>fn());clearInterval(this.presenceTimer);clearTimeout(this.recordTimer);if(this.recorder?.state==='recording')this.recorder.stop();if(this.call)void this.endCall();void this.presence.remove();}
